def word_wrap(text: str, width: int) -> list:
    """Greedily pack whitespace-separated words into lines of at most `width` chars."""
    if width < 1:
        raise ValueError("width must be at least 1")

    words = text.split()
    if not words:
        return []

    lines = []
    current = words[0]
    for word in words[1:]:
        if len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            lines.append(current)
            current = word
    lines.append(current)
    return lines
```

Words longer than `width` simply end up alone on their own line, unbroken, since a new line is started whenever the word doesn't fit alongside the current content.
